mapper.select:
select a.*, c.name as eventSourceName
from sys_event_rule a
left join sys_classify c on a.event_source = c.code


        and a.rule_name like concat('%', #{ruleName}, '%')


        and a.event_level = #{eventLevel}


        and a.event_source = #{eventSource}


        and a.action_type = #{actionType}


        and a.status = #{status}


        and a.create_time >= #{beginTime}


        and a.create_time <= #{endTime}


order by a.create_time desc, a.id desc
